//! MCP-only stdout; startup diagnostics are bounded and never include credential values.
use clap::Parser;
use std::path::PathBuf;

#[derive(Parser)]
#[command(about = "Connect a local MCP client to one scoped Nova Memory connection over stdio")]
struct Cli {
    /// Private setup file generated by the local workbench. No token on the command line.
    #[arg(long)]
    config: PathBuf,
    /// Optional MCP-only loopback listener for an independently configured authenticated tunnel.
    /// Does not start a tunnel, expose Owner routes or listen on a public interface.
    #[arg(long)]
    http_bind: Option<std::net::SocketAddr>,
}

async fn http_gateway(path: PathBuf, bind: std::net::SocketAddr) -> anyhow::Result<()> {
    anyhow::ensure!(bind.ip().is_loopback(), "NOVA_GATEWAY_LOOPBACK_ONLY");
    let listener = tokio::net::TcpListener::bind(bind).await?;
    let address = listener.local_addr()?;
    let app = nova_review::local_mcp_gateway::router(path, address.to_string())?;
    eprintln!("Nova Memory MCP gateway: http://{address}/mcp");
    Ok(axum::serve(listener, app).await?)
}

#[tokio::main]
async fn main() {
    let cli = Cli::parse();
    let result = tokio::select! {
        result = async {
            if let Some(bind) = cli.http_bind {
                http_gateway(cli.config, bind).await
            } else {
                nova_review::local_mcp_bridge::run(&cli.config, tokio::io::stdin(), tokio::io::stdout()).await
            }
        } => result,
        // Tokio stdin uses a blocking reader; exit this owned adapter without waiting for it.
        _ = tokio::signal::ctrl_c() => std::process::exit(0),
    };
    if result.is_err() {
        eprintln!(
            "NOVA_LOCAL_CONNECTION_FAILED: check the private configuration, local service and connection permissions."
        );
        std::process::exit(1);
    }
}
